import{_ as a,o as e,c as s,a3 as n}from"./chunks/framework.BPaanrMb.js";const _=JSON.parse('{"title":"AI 自动驾驶问题回答协议","description":"使用 WheelOS Docs 分析自动驾驶问题时的固定判断、排查、验证和引用流程。","frontmatter":{"title":"AI 自动驾驶问题回答协议","description":"使用 WheelOS Docs 分析自动驾驶问题时的固定判断、排查、验证和引用流程。","status":"仓库事实","content_type":"methodology","keywords":["AI Agent","故障排查","引用","证据","产品规格"]},"headers":[],"relativePath":"knowledge/answer-protocol.md","filePath":"knowledge/answer-protocol.md","lastUpdated":1794551845000}'),d={name:"knowledge/answer-protocol.md"};function l(o,t,p,r,i,c){return e(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="ai-自动驾驶问题回答协议" tabindex="-1">AI 自动驾驶问题回答协议 <a class="header-anchor" href="#ai-自动驾驶问题回答协议" aria-label="Permalink to &quot;AI 自动驾驶问题回答协议&quot;">​</a></h1><p>当 AI 使用本知识库设计方案、分析故障或评估产品时，必须按以下顺序工作。该协议的目的不是让回答更长，而是阻止未经验证的推测被当成事实。</p><h2 id="_1-先建立问题对象" tabindex="-1">1. 先建立问题对象 <a class="header-anchor" href="#_1-先建立问题对象" aria-label="Permalink to &quot;1. 先建立问题对象&quot;">​</a></h2><p>把用户描述转换成结构化信息：</p><table tabindex="0"><thead><tr><th>字段</th><th>必须回答</th></tr></thead><tbody><tr><td>现象</td><td>车辆或系统实际做了什么</td></tr><tr><td>期望</td><td>应该做什么</td></tr><tr><td>频率</td><td>每次、偶发、特定场景还是无法复现</td></tr><tr><td>边界</td><td>车辆/仿真、速度、天气、地图、传感器组合</td></tr><tr><td>版本</td><td>WheelOS 提交、模块版本、配置版本</td></tr><tr><td>数据</td><td>话题、时间戳、坐标系、日志、回放</td></tr><tr><td>内容状态</td><td>产品规格、仓库事实、设计建议还是已有验证证据</td></tr><tr><td>风险</td><td>是否涉及执行器、道路安全或不可逆动作</td></tr></tbody></table><p>缺少关键字段时，先输出需要补充的数据，不要直接给出确定性方案。</p><h2 id="_2-按数据链路定位" tabindex="-1">2. 按数据链路定位 <a class="header-anchor" href="#_2-按数据链路定位" aria-label="Permalink to &quot;2. 按数据链路定位&quot;">​</a></h2><p>优先查找首次偏离预期的层级：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>传感器 -&gt; 驱动 -&gt; 消息 -&gt; 时间同步 -&gt; 坐标变换</span></span>
<span class="line"><span>       -&gt; 定位/感知/预测 -&gt; 规划 -&gt; 控制 -&gt; 底盘反馈</span></span></code></pre></div><p>不要因为现象出现在规划模块，就默认根因在规划模块。</p><h2 id="_3-设计最小实验" tabindex="-1">3. 设计最小实验 <a class="header-anchor" href="#_3-设计最小实验" aria-label="Permalink to &quot;3. 设计最小实验&quot;">​</a></h2><p>一次只改变一个关键变量；保留基线；定义数值阈值；记录完整版本和配置；同时保留成功与失败样本。实验应优先选择可回放、可自动化、风险最低的环境，再逐步提升验证等级。</p><h2 id="_4-输出结论" tabindex="-1">4. 输出结论 <a class="header-anchor" href="#_4-输出结论" aria-label="Permalink to &quot;4. 输出结论&quot;">​</a></h2><p>结论必须使用以下格式：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>页面类型：产品 / 知识 / 证据 / 路线图 / 社区</span></span>
<span class="line"><span>判断：产品配置 / 仓库事实 / 设计建议 / 部分验证 / 已验证 / 计划能力 / 当前未知</span></span>
<span class="line"><span>证据：页面 URL、证据 ID、仓库提交或正式产品规格</span></span>
<span class="line"><span>方案：具体改动和复现步骤</span></span>
<span class="line"><span>结果：指标、基线、样本量和原始工件</span></span>
<span class="line"><span>边界：未覆盖的硬件、场景、版本和安全限制</span></span>
<span class="line"><span>下一步：最小的补充实验</span></span></code></pre></div><p><code>已验证</code> 只能引用 <code>evidence/registry.json</code> 中的记录。没有证据 ID 时，不能使用“WheelOS 已验证”或“真实车辆已证明”等表述。产品页只能证明当前方案的配置与商务范围，不能单独证明安全、性能或场地适用性。</p><h2 id="_5-双语与冲突处理" tabindex="-1">5. 双语与冲突处理 <a class="header-anchor" href="#_5-双语与冲突处理" aria-label="Permalink to &quot;5. 双语与冲突处理&quot;">​</a></h2><ul><li>中英文页面应表达相同事实、数字、状态和限制。</li><li>如果英文与中文内容冲突，报告差异和两个页面 URL，不要自行选择更有利的版本。</li><li>产品规格、证据记录和知识页面的结论强度不同；发生冲突时，分别说明问题类型，不要合并成一个“已验证”结论。</li></ul>`,18)])])}const u=a(d,[["render",l]]);export{_ as __pageData,u as default};
